{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2157-01-20 21:21:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I’ll be helping take care of you during this hospital stay. I know you're here for abdominal pain again. Can you tell me about it?"
    },
    {
      "turn_number": 2,
      "time": "2157-01-20 21:22:30",
      "speaker": "Patient",
      "text": "Yes… it’s that same gastroparesis pain. Sharp, in the upper middle, started two days ago. Nausea, threw up twice. Can’t keep anything down."
    },
    {
      "turn_number": 3,
      "time": "2157-01-20 21:23:15",
      "speaker": "Doctor",
      "text": "I see. Any fever at home?"
    },
    {
      "turn_number": 4,
      "time": "2157-01-20 21:23:45",
      "speaker": "Patient",
      "text": "Yeah, low grade. Around 100. But no chills or chest pain."
    },
    {
      "turn_number": 5,
      "time": "2157-01-20 21:24:20",
      "speaker": "Doctor",
      "text": "Okay. You’re on a lot of medications already. We’ll continue those unless something needs adjusting. We’re going to start with IV fluids and pain control."
    },
    {
      "turn_number": 6,
      "time": "2157-01-20 21:25:00",
      "speaker": "Patient",
      "text": "Thank you. I just want the pain to stop. I’ve been through this so many times."
    },
    {
      "turn_number": 7,
      "time": "2157-01-20 21:25:30",
      "speaker": "Doctor",
      "text": "I understand. We’ll follow the same protocol that’s helped before. No imaging today since your symptoms match prior flares."
    },
    {
      "turn_number": 8,
      "time": "2157-01-21 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. How’s the pain today?"
    },
    {
      "turn_number": 9,
      "time": "2157-01-21 08:16:20",
      "speaker": "Patient",
      "text": "Still there. Around a 7. Nausea’s a little better. Can I try sipping water?"
    },
    {
      "turn_number": 10,
      "time": "2157-01-21 08:17:30",
      "speaker": "Doctor",
      "text": "We’ll start with small sips. But you need to stay NPO for now. We don’t want to trigger vomiting again."
    },
    {
      "turn_number": 11,
      "time": "2157-01-21 08:18:45",
      "speaker": "Patient",
      "text": "I know, but I hate being on IVs. I feel like I’m not healing if I can’t eat."
    },
    {
      "turn_number": 12,
      "time": "2157-01-21 08:19:30",
      "speaker": "Doctor",
      "text": "I hear you. But your stomach isn’t emptying well. Remember the gastric emptying test showed 81% still in your stomach after four hours?"
    },
    {
      "turn_number": 13,
      "time": "2157-01-21 08:20:15",
      "speaker": "Patient",
      "text": "Right… gastroparesis. So this isn’t just in my head."
    },
    {
      "turn_number": 14,
      "time": "2157-01-21 08:21:00",
      "speaker": "Doctor",
      "text": "No, it’s very real. And we’re not questioning that. We’re just managing it step by step."
    },
    {
      "turn_number": 15,
      "time": "2157-01-22 09:00:00",
      "speaker": "Doctor",
      "text": "Labs came back. Your lipase is slightly elevated at 95, but liver tests and blood counts are normal."
    },
    {
      "turn_number": 16,
      "time": "2157-01-22 09:01:20",
      "speaker": "Patient",
      "text": "Is that pancreatitis again?"
    },
    {
      "turn_number": 17,
      "time": "2157-01-22 09:02:10",
      "speaker": "Doctor",
      "text": "Not likely. Your MRCP and past ERCPs showed no blockages or acute issues. The slight lipase rise may be from chronic changes, not a new flare."
    },
    {
      "turn_number": 18,
      "time": "2157-01-22 09:03:00",
      "speaker": "Patient",
      "text": "So it’s still the same chronic pancreatitis and motility problem?"
    },
    {
      "turn_number": 19,
      "time": "2157-01-22 09:03:45",
      "speaker": "Doctor",
      "text": "Yes. The pancreas shows some old damage, but no active inflammation. We’ll keep focusing on symptom control."
    },
    {
      "turn_number": 20,
      "time": "2157-01-23 10:30:00",
      "speaker": "Doctor",
      "text": "How are you feeling today?"
    },
    {
      "turn_number": 21,
      "time": "2157-01-23 10:31:15",
      "speaker": "Patient",
      "text": "Pain’s down to a 5. I haven’t vomited. Can I try clear soup?"
    },
    {
      "turn_number": 22,
      "time": "2157-01-23 10:32:30",
      "speaker": "Doctor",
      "text": "We can try small amounts of clear liquids. But I need to remind you—no solid food yet, and no eating when you’re supposed to be NPO."
    },
    {
      "turn_number": 23,
      "time": "2157-01-23 10:33:45",
      "speaker": "Patient",
      "text": "I know… I did have a cracker yesterday when no one was in. I was so hungry."
    },
    {
      "turn_number": 24,
      "time": "2157-01-23 10:34:30",
      "speaker": "Doctor",
      "text": "I appreciate you telling me. But doing that can set us back. The protocol works best when we stick to it together."
    },
    {
      "turn_number": 25,
      "time": "2157-01-23 10:35:15",
      "speaker": "Patient",
      "text": "I’m sorry. I just get desperate."
    },
    {
      "turn_number": 26,
      "time": "2157-01-23 10:36:00",
      "speaker": "Doctor",
      "text": "It’s okay. Let’s focus on moving forward. We’ll advance your diet slowly, safely."
    },
    {
      "turn_number": 27,
      "time": "2157-01-24 08:00:00",
      "speaker": "Doctor",
      "text": "Morning. Pain level?"
    },
    {
      "turn_number": 28,
      "time": "2157-01-24 08:01:10",
      "speaker": "Patient",
      "text": "Around 4. I kept the apple juice down all night. That’s progress, right?"
    },
    {
      "turn_number": 29,
      "time": "2157-01-24 08:02:00",
      "speaker": "Doctor",
      "text": "That’s great progress. We’ll keep you on clear liquids today and see how you do."
    },
    {
      "turn_number": 30,
      "time": "2157-01-24 08:03:15",
      "speaker": "Patient",
      "text": "Can I go home soon?"
    },
    {
      "turn_number": 31,
      "time": "2157-01-24 08:04:00",
      "speaker": "Doctor",
      "text": "Not yet. We need to make sure you can tolerate more and that your pain stays controlled without IV meds."
    },
    {
      "turn_number": 32,
      "time": "2157-01-25 09:15:00",
      "speaker": "Doctor",
      "text": "Labs this morning show your lipase dropped to 81. Glucose was 91—normal."
    },
    {
      "turn_number": 33,
      "time": "2157-01-25 09:16:20",
      "speaker": "Patient",
      "text": "Is that good?"
    },
    {
      "turn_number": 34,
      "time": "2157-01-25 09:17:00",
      "speaker": "Doctor",
      "text": "Yes. It means no worsening of pancreatic issues. We also saw a mild low sugar earlier, which can happen with chronic pancreatitis."
    },
    {
      "turn_number": 35,
      "time": "2157-01-25 09:18:15",
      "speaker": "Patient",
      "text": "Should I be worried about diabetes?"
    },
    {
      "turn_number": 36,
      "time": "2157-01-25 09:19:00",
      "speaker": "Doctor",
      "text": "Not right now. Your sugars are mostly normal. We’ll watch it, especially since your pancreas has some scarring."
    },
    {
      "turn_number": 37,
      "time": "2157-01-26 10:00:00",
      "speaker": "Doctor",
      "text": "You’ve gone two days without vomiting. Pain is stable. How are you feeling mentally?"
    },
    {
      "turn_number": 38,
      "time": "2157-01-26 10:01:20",
      "speaker": "Patient",
      "text": "Anxious. I hate being stuck here. But my husband says I’ve seemed less down since the pain eased."
    },
    {
      "turn_number": 39,
      "time": "2157-01-26 10:02:30",
      "speaker": "Doctor",
      "text": "That makes sense. We’re continuing your usual meds—venlafaxine, clonazepam, prazosin. Your husband mentioned you’re taking gabapentin twice a day now, not three times?"
    },
    {
      "turn_number": 40,
      "time": "2157-01-26 10:03:45",
      "speaker": "Patient",
      "text": "Yes, it makes me too sleepy. I cut back."
    },
    {
      "turn_number": 41,
      "time": "2157-01-26 10:04:30",
      "speaker": "Doctor",
      "text": "Okay. Let’s keep it at twice daily for now. We can discuss adjustments with your psychiatrist later."
    },
    {
      "turn_number": 42,
      "time": "2157-01-27 08:30:00",
      "speaker": "Doctor",
      "text": "Today we’d like to try advancing your diet to soft foods—like mashed potatoes or oatmeal. How does that sound?"
    },
    {
      "turn_number": 43,
      "time": "2157-01-27 08:31:15",
      "speaker": "Patient",
      "text": "I’d love that. Real food feels like a step toward going home."
    },
    {
      "turn_number": 44,
      "time": "2157-01-27 08:32:00",
      "speaker": "Doctor",
      "text": "Exactly. But we’ll go slow. Small portions, frequent checks."
    },
    {
      "turn_number": 45,
      "time": "2157-01-28 09:00:00",
      "speaker": "Doctor",
      "text": "You tolerated the soft diet well. No nausea, pain at 3. We’re making good progress."
    },
    {
      "turn_number": 46,
      "time": "2157-01-28 09:01:15",
      "speaker": "Patient",
      "text": "Can I go home tomorrow?"
    },
    {
      "turn_number": 47,
      "time": "2157-01-28 09:02:00",
      "speaker": "Doctor",
      "text": "Possibly. We’ll see how today goes. You mentioned wanting a new GI doctor and pain specialist?"
    },
    {
      "turn_number": 48,
      "time": "2157-01-28 09:03:10",
      "speaker": "Patient",
      "text": "Yes. I need someone who understands this isn’t just anxiety. It’s real."
    },
    {
      "turn_number": 49,
      "time": "2157-01-28 09:04:00",
      "speaker": "Doctor",
      "text": "Absolutely. I’ll refer you to a new GI and a pain management specialist. We’ll make sure your records go with you."
    },
    {
      "turn_number": 50,
      "time": "2157-01-29 10:00:00",
      "speaker": "Doctor",
      "text": "You’ve had no pain requiring IV meds for over 48 hours. You’re eating soft foods, moving around fine. We think you’re ready for discharge."
    },
    {
      "turn_number": 51,
      "time": "2157-01-29 10:01:15",
      "speaker": "Patient",
      "text": "Really? That’s great. What about my meds?"
    },
    {
      "turn_number": 52,
      "time": "2157-01-29 10:02:00",
      "speaker": "Doctor",
      "text": "You’ll go home with acetaminophen, hydrocodone for breakthrough pain, metoclopramide for nausea, and your usual meds like erythromycin and ranitidine."
    },
    {
      "turn_number": 53,
      "time": "2157-01-29 10:03:15",
      "speaker": "Patient",
      "text": "And the cream for my skin?"
    },
    {
      "turn_number": 54,
      "time": "2157-01-29 10:04:00",
      "speaker": "Doctor",
      "text": "Yes, triamcinolone cream twice a day, and Sarna lotion if you have itching. Your skin looks clear now."
    },
    {
      "turn_number": 55,
      "time": "2157-01-29 10:05:00",
      "speaker": "Patient",
      "text": "Thank you. I’ll follow up with the new doctors?"
    },
    {
      "turn_number": 56,
      "time": "2157-01-29 10:06:00",
      "speaker": "Doctor",
      "text": "Yes. And call us if pain worsens, or you can’t keep liquids down. Otherwise, see your PCP in a week."
    },
    {
      "turn_number": 57,
      "time": "2157-01-30 07:00:00",
      "speaker": "Doctor",
      "text": "Final check before discharge. Pain level?"
    },
    {
      "turn_number": 58,
      "time": "2157-01-30 07:01:10",
      "speaker": "Patient",
      "text": "3. I had toast and tea this morning. Felt good."
    },
    {
      "turn_number": 59,
      "time": "2157-01-30 07:02:00",
      "speaker": "Doctor",
      "text": "Excellent. Your physical exam is normal. Mild tenderness in the left upper quadrant, but no guarding."
    },
    {
      "turn_number": 60,
      "time": "2157-01-30 07:03:15",
      "speaker": "Patient",
      "text": "I’m ready to go home."
    },
    {
      "turn_number": 61,
      "time": "2157-01-30 07:04:00",
      "speaker": "Doctor",
      "text": "You’re cleared. We’ll get your discharge papers and prescriptions."
    },
    {
      "turn_number": 62,
      "time": "2157-01-30 07:05:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor. I know this is hard to treat, but you listened."
    },
    {
      "turn_number": 63,
      "time": "2157-01-30 07:06:00",
      "speaker": "Doctor",
      "text": "You’re doing the hard work. Keep following the plan, and reach out if you need help."
    },
    {
      "turn_number": 64,
      "time": "2157-01-30 07:07:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 65,
      "time": "2157-01-30 07:08:00",
      "speaker": "Doctor",
      "text": "Take care. We’ll see you in follow-up."
    }
  ],
  "summary": {
    "admission_start": "2157-01-20 21:21:00",
    "admission_end": "2157-01-30 15:30:00",
    "summary_paragraph": "A woman with a history of chronic abdominal pain, gastroparesis, anxiety, depression, and PTSD was admitted for an acute flare of abdominal pain consistent with prior episodes. She presented with epigastric pain, nausea, and vomiting, and was managed with an established inpatient protocol including IV fluids, pain control, and gradual dietary advancement. Labs showed mild, stable lipase elevation without evidence of acute pancreatitis. She improved over the course of the admission, tolerating soft foods and reporting decreased pain. No new complications arose. She was discharged home in stable condition with referrals to a new GI specialist and pain management, and a plan to continue home medications including erythromycin, metoclopramide, and hydrocodone as needed.",
    "problems": [
      "Gastroparesis",
      "Other chronic pancreatitis",
      "Functional dyspepsia",
      "Anxiety disorder, unspecified",
      "Major depressive disorder, single episode, unspecified",
      "Unspecified hearing loss, unspecified ear",
      "Post-traumatic stress disorder, unspecified",
      "Left upper quadrant pain",
      "Other seasonal allergic rhinitis",
      "Unspecified contact dermatitis, unspecified cause"
    ]
  }
}
